 DateTime agendaDate=DateTime.Today;bool agendaWeek;
 static readonly string[] ReminderNames={"Aucun rappel","À l’heure prévue","5 minutes avant","15 minutes avant","30 minutes avant","1 heure avant","1 jour avant"};
 static readonly string[] RepeatNames={"Une seule fois","Chaque jour","Chaque semaine","Chaque mois"};
 static readonly string[] RepeatCodes={"none","daily","weekly","monthly"};
 bool ReadDate(TextBox input,bool required,out string date){date="";DateTime value;if(String.IsNullOrWhiteSpace(input.Text))return !required;if(!DateTime.TryParseExact(input.Text.Trim(),new[]{"dd/MM/yyyy","yyyy-MM-dd"},CultureInfo.InvariantCulture,DateTimeStyles.None,out value))return false;date=value.ToString("yyyy-MM-dd");return true;}
 ComboBox ReminderCombo(int lead){int index=Array.IndexOf(Schedule.Leads,lead);return Combo(ReminderNames,ReminderNames[Math.Max(0,index)]);}
 internal WorkTask EditTask(WorkTask task){StackPanel body,actions;var w=Dialog(task==null?"Nouvelle tâche":"Modifier la tâche",out body,out actions,800);var title=new TextBox{Text=task==null?"":task.title,MaxLength=180};Field(body,"Qu’avez-vous à faire ?",title);var project=Combo(owner.AllProjects(),task==null?owner.AllProjects()[0]:task.project);Field(body,"Projet",project);var priority=Combo(new[]{"Normale","Haute","Basse"},task==null?"Normale":task.priority);Field(body,"Priorité",priority);var state=Combo(new[]{"À faire","En cours","Terminé"},task==null?"À faire":task.status=="done"?"Terminé":task.status=="doing"?"En cours":"À faire");Field(body,"Statut",state);var date=new TextBox{Text=task!=null&&!String.IsNullOrEmpty(task.due)?Schedule.Day(task.due).ToString("dd/MM/yyyy"):"",MaxLength=10};Field(body,"Échéance · JJ/MM/AAAA (facultatif)",date);var time=new TextBox{Text=task==null||String.IsNullOrEmpty(task.dueTime)?"09:00":task.dueTime,MaxLength=5};Field(body,"Heure · HH:mm",time);var repeat=Combo(RepeatNames,RepeatNames[Math.Max(0,Array.IndexOf(RepeatCodes,task==null?"none":task.repeat))]);Field(body,"Répétition",repeat);var remind=ReminderCombo(task==null?-1:task.remindMinutes);Field(body,"Notification Windows",remind);body.Children.Add(T("Une tâche terminée crée la prochaine occurrence, à partir de son échéance. Pour arrêter la série, choisissez « Une seule fois » sur la prochaine tâche.",11,Muted,new Thickness(0,0,0,16)));var notes=new TextBox{Text=task==null?"":task.notes,Height=90,AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};Field(body,"Notes",notes);var error=T("",12,B("#F0AF82"));body.Children.Add(error);WorkTask result=null;if(task!=null&&store.Value.tasks.Contains(task))actions.Children.Add(Btn("Supprimer",delegate{if(System.Windows.Forms.MessageBox.Show("Supprimer cette occurrence ? Les autres tâches de la série sont conservées.","Mon espace",System.Windows.Forms.MessageBoxButtons.YesNo)==System.Windows.Forms.DialogResult.Yes){if(DeleteWithUndo("task",task.id))w.DialogResult=false;}},false,true));actions.Children.Add(Btn("Annuler",delegate{w.DialogResult=false;},false,true));actions.Children.Add(Btn("Enregistrer",delegate{string due;if(String.IsNullOrWhiteSpace(title.Text)){title.Focus();return;}if(!ReadDate(date,repeat.SelectedIndex>0||remind.SelectedIndex>0,out due)){error.Text="Indiquez une date valide. Répétitions et rappels nécessitent une échéance.";date.Focus();return;}if(!Schedule.ValidTime(time.Text.Trim())){error.Text="L’heure doit être au format HH:mm, entre 00:00 et 23:59.";time.Focus();return;}result=new WorkTask{id=task==null||String.IsNullOrEmpty(task.id)?Guid.NewGuid().ToString():task.id,title=title.Text.Trim(),project=Convert.ToString(project.SelectedItem),priority=Convert.ToString(priority.SelectedItem),status=state.SelectedIndex==2?"done":state.SelectedIndex==1?"doing":"todo",due=due,dueTime=String.IsNullOrEmpty(due)?"":time.Text.Trim(),notes=notes.Text,repeat=RepeatCodes[repeat.SelectedIndex],remindMinutes=Schedule.Leads[remind.SelectedIndex],repeatDay=task!=null&&task.due==due&&task.repeatDay>0?task.repeatDay:String.IsNullOrEmpty(due)?1:Schedule.Day(due).Day,nextId=task==null?"":task.nextId,lastReminder=task==null?"":task.lastReminder,completedOn=task==null?"":task.completedOn};w.DialogResult=true;},true));w.Loaded+=delegate{title.Focus();};return ShowWindow(w)==true?result:null;}
 void EditAppointment(CalendarEvent existing,DateTime day){StackPanel body,actions;var w=Dialog(existing==null?"Nouveau rendez-vous":"Modifier le rendez-vous",out body,out actions,770);var title=new TextBox{Text=existing==null?"":existing.title,MaxLength=200};Field(body,"Titre",title);var date=new TextBox{Text=existing==null?day.ToString("dd/MM/yyyy"):Schedule.Day(existing.date).ToString("dd/MM/yyyy"),MaxLength=10};Field(body,"Date · JJ/MM/AAAA",date);var time=new TextBox{Text=existing==null?"09:00":existing.time,MaxLength=5};Field(body,"Heure · HH:mm",time);var duration=new TextBox{Text=existing==null?"60":existing.duration.ToString(),MaxLength=4};Field(body,"Durée en minutes",duration);var project=Combo(new[]{"Personnel / sans projet"}.Concat(owner.AllProjects()),existing==null||String.IsNullOrEmpty(existing.project)?"Personnel / sans projet":existing.project);Field(body,"Projet",project);var remind=ReminderCombo(existing==null?15:existing.remindMinutes);Field(body,"Notification Windows",remind);var notes=new TextBox{Text=existing==null?"":existing.notes,AcceptsReturn=true,Height=90,MaxLength=10000,TextWrapping=TextWrapping.Wrap};Field(body,"Notes / lieu",notes);var error=T("",12,B("#F0AF82"));body.Children.Add(error);if(existing!=null)actions.Children.Add(Btn("Supprimer",delegate{if(System.Windows.Forms.MessageBox.Show("Supprimer ce rendez-vous ?","Mon espace",System.Windows.Forms.MessageBoxButtons.YesNo)==System.Windows.Forms.DialogResult.Yes){if(DeleteWithUndo("event",existing.id))w.DialogResult=false;}},false,true));actions.Children.Add(Btn("Annuler",delegate{w.DialogResult=false;},false,true));actions.Children.Add(Btn("Enregistrer",delegate{string parsed;int minutes;if(String.IsNullOrWhiteSpace(title.Text)||!ReadDate(date,true,out parsed)||!Schedule.ValidTime(time.Text.Trim())||!Int32.TryParse(duration.Text,out minutes)||minutes<5||minutes>1440){error.Text="Vérifiez le titre, la date, l’heure et la durée (5 à 1 440 min).";error.BringIntoView();return;}var e=new CalendarEvent{id=existing==null?Guid.NewGuid().ToString():existing.id,title=title.Text.Trim(),date=parsed,time=time.Text.Trim(),duration=minutes,project=project.SelectedIndex==0?"":Convert.ToString(project.SelectedItem),notes=notes.Text,remindMinutes=Schedule.Leads[remind.SelectedIndex],lastReminder=existing==null?"":existing.lastReminder};if(existing!=null)store.Value.events.Remove(existing);store.Value.events.Add(e);if(!owner.Save()){store.Value.events.Remove(e);if(existing!=null)store.Value.events.Add(existing);return;}w.DialogResult=true;},true));ShowWindow(w);Refresh();}
 void Agenda(StackPanel root){AgendaV2(root);}
 StackPanel DaySchedule(DateTime day,bool compact){var body=new StackPanel();string date=day.ToString("yyyy-MM-dd");foreach(var e in store.Value.events.Where(e=>e.date==date).OrderBy(e=>e.time)){var appointment=e;var ending=Schedule.At(e.date,e.time).AddMinutes(e.duration);string end=ending.ToString("HH:mm")+(ending.Date>day.Date?" (+1 j)":"");var b=Btn(e.time+" – "+end+"   ·   "+e.title,delegate{EditAppointment(appointment,day);},false,true);b.HorizontalContentAlignment=HorizontalAlignment.Left;var text=T(e.time+" – "+end+"   ·   "+e.title,13,Accent);text.TextWrapping=TextWrapping.Wrap;b.Content=text;PinMenu(b,"event",e.id,e.title);body.Children.Add(b);if(!compact&&!String.IsNullOrWhiteSpace(e.notes))body.Children.Add(T(e.notes,12,Muted,new Thickness(12,0,0,12)));}AppendGoogleDay(body,day);var tasks=store.Value.tasks.Where(t=>t.due==date).OrderBy(t=>t.dueTime).ToList();if(tasks.Count>0)body.Children.Add(TaskList(tasks,0));if(!body.Children.Cast<UIElement>().Any())body.Children.Add(T("Rien de prévu.",12,Muted));return body;}
 StackPanel TodaySchedule(bool compact){var root=new StackPanel();var late=store.Value.tasks.Where(t=>t.status!="done"&&!String.IsNullOrEmpty(t.due)&&String.CompareOrdinal(t.due,DateTime.Today.ToString("yyyy-MM-dd"))<0).OrderBy(t=>t.due).ToList();if(late.Count>0){root.Children.Add(T(late.Count+" tâche(s) en retard",12,Accent,new Thickness(0,0,0,8)));root.Children.Add(TaskList(late,compact?2:4));}root.Children.Add(DaySchedule(DateTime.Today,compact));return root;}
 void RemindersPage(StackPanel root){BudgetReminderOverview(root);root.Children.Add(T("Notifications "+(store.Value.settings.Notifications?"activées":"désactivées")+" · application ouverte ou réduite",12,Muted,new Thickness(0,0,0,16)));root.Children.Add(Card("Aujourd’hui & retards",TodaySchedule(false)));var upcoming=new StackPanel();foreach(var e in store.Value.events.Where(e=>Schedule.At(e.date,e.time)>=DateTime.Now).OrderBy(e=>e.date+e.time).Take(10)){var item=e;upcoming.Children.Add(Btn(Schedule.Day(e.date).ToString("dd MMM")+" · "+e.time+" · "+e.title,delegate{EditAppointment(item,Schedule.Day(item.date));},false,true));}var card=Card("Prochains rendez-vous",upcoming);card.Margin=new Thickness(0,16,0,16);root.Children.Add(card);root.Children.Add(Card("Tâches à venir",TaskList(store.Value.tasks.Where(t=>t.status!="done"&&!String.IsNullOrEmpty(t.due)&&String.CompareOrdinal(t.due,DateTime.Today.ToString("yyyy-MM-dd"))>0).OrderBy(t=>t.due),0)));}
 void AddAgendaSettings(StackPanel body){var notifications=new CheckBox{Content="Activer les rappels Windows",IsChecked=store.Value.settings.Notifications,Margin=new Thickness(0,0,0,12)};notifications.Click+=delegate{store.Value.settings.Notifications=notifications.IsChecked==true;owner.Save();};body.Children.Add(notifications);body.Children.Add(T("Rappels actifs tant que l’application est ouverte ou réduite. Windows peut les masquer en mode Ne pas déranger.",11,Muted,new Thickness(0,0,0,12)));var bot=new CheckBox{Content="Afficher mon module bot Discord (facultatif)",IsChecked=store.Value.settings.EnableBotModule,Margin=new Thickness(0,0,0,10)};bot.Click+=delegate{store.Value.settings.EnableBotModule=bot.IsChecked==true;owner.Save();};body.Children.Add(bot);body.Children.Add(T("Désactivé par défaut pour chaque nouvel utilisateur. La connexion réelle au bot sera configurée séparément.",11,Muted,new Thickness(0,0,0,20)));}
 internal void PreviewAgenda(string path){var e=new CalendarEvent{id="preview-rdv",title="Point sur les projets",date=DateTime.Today.ToString("yyyy-MM-dd"),time="14:30",notes="Faire le point et préparer les prochaines priorités."};store.Value.events.Add(e);selected="Agenda";agendaDate=DateTime.Today;agendaWeek=false;Refresh();Preview(path+"-agenda.png");agendaWeek=true;Refresh();Preview(path+"-semaine.png");previewPrefix=path;EditAppointment(null,DateTime.Today);previewPrefix=null;store.Value.events.Remove(e);}
